<file path="src/credits.js">
import { ok, fail } from './result.js';
import { invoiceTotals } from './invoices.js';
import { isValidDate } from './dates.js';

function nextCreditNoteNumber(existingNumbers, date) {
  const year = date.slice(0, 4);

  // Find the maximum counter for this year
  const pattern = new RegExp(`^CN-${year}-(\\d{4})$`);
  let maxCounter = 0;

  for (const num of existingNumbers) {
    const match = pattern.exec(num);
    if (match) {
      const counter = parseInt(match[1], 10);
      maxCounter = Math.max(maxCounter, counter);
    }
  }

  const nextCounter = maxCounter + 1;
  return `CN-${year}-${String(nextCounter).padStart(4, '0')}`;
}

/**
 * Create a credit note (refund) for an issued invoice.
 * @param {object} invoice
 * @param {{ amount: number, reason: string, date: string }}
 * @param {Array<string>} existingNumbers - Both invoice and credit note numbers already used
 */
export function createCreditNote(invoice, { amount, reason, date }, existingNumbers) {
  // Check invoice is issued, partially_paid, or paid
  if (!['issued', 'partially_paid', 'paid'].includes(invoice.status)) {
    return fail('NOT_ISSUED');
  }

  // Validate date
  if (!isValidDate(date)) return fail('DATE_INVALID');

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  // Check amount is not more than invoice total
  const invoiceTotal = invoiceTotals(invoice).total;
  if (amount > invoiceTotal) return fail('CREDIT_TOO_HIGH');

  // Get next credit note number
  const number = nextCreditNoteNumber(existingNumbers, date);

  return ok({
    number,
    invoiceNumber: invoice.number,
    customerId: invoice.customerId,
    amount,
    reason,
    date,
  });
}
</file>

<file path="src/customers.js">
import { readFileSync } from 'node:fs';
import { ok, fail } from './result.js';

const CUSTOMERS = JSON.parse(readFileSync(new URL('../data/customers.json', import.meta.url), 'utf8'));

export const TIER_DISCOUNTS = {
  gold: 5,
  silver: 2.5,
  standard: 0,
};

/**
 * Normalize a customer ID: trim whitespace and convert to uppercase.
 * @param {string} id
 * @returns {string}
 */
export function normalizeId(id) {
  return String(id).trim().toUpperCase();
}

/**
 * All customers: { id, name, email, country, tier }.
 */
export function listCustomers() {
  return CUSTOMERS.map((c) => ({ ...c }));
}

/**
 * One customer by id.
 * @param {string} id
 */
export function getCustomer(id) {
  const normalizedId = normalizeId(id);
  const c = CUSTOMERS.find((x) => x.id === normalizedId);
  return c ? ok({ ...c }) : fail('CUSTOMER_NOT_FOUND');
}

/**
 * Check a customer record before it is stored.
 * @param {{ id?: string, name?: string, email?: string }} c
 */
export function validateCustomer(c) {
  if (!c || !c.id || !c.name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email ?? '')) return fail('CUSTOMER_INVALID');
  return ok({ ...c });
}
</file>

<file path="src/dates.js">
/**
 * Check if a date string is valid in YYYY-MM-DD format.
 * @param {string} dateString
 * @returns {boolean}
 */
export function isValidDate(dateString) {
  // Check format is YYYY-MM-DD
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateString)) return false;

  // Check it's a valid date in UTC
  const date = new Date(`${dateString}T00:00:00Z`);
  const [year, month, day] = dateString.split('-').map(Number);

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() + 1 === month &&
    date.getUTCDate() === day
  );
}

/**
 * Add n days to a date string, returning a new date string in YYYY-MM-DD format.
 * All arithmetic is done in UTC.
 * @param {string} dateString - Date in YYYY-MM-DD format
 * @param {number} n - Number of days to add (can be negative)
 * @returns {string} - New date in YYYY-MM-DD format
 */
export function addDays(dateString, n) {
  const date = new Date(`${dateString}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + n);

  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const day = String(date.getUTCDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
}

/**
 * Calculate the number of whole days between two dates (b - a) in UTC.
 * @param {string} a - Date in YYYY-MM-DD format (start)
 * @param {string} b - Date in YYYY-MM-DD format (end)
 * @returns {number} - Number of whole days (b - a)
 */
export function daysBetween(a, b) {
  const dateA = new Date(`${a}T00:00:00Z`);
  const dateB = new Date(`${b}T00:00:00Z`);

  const diffMs = dateB.getTime() - dateA.getTime();
  const diffDays = diffMs / (1000 * 60 * 60 * 24);

  return Math.floor(diffDays);
}
</file>

