<file path="src/export.js">
import { invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Format cents as euros string: 123456 -> "1234.56"
 * @param {number} cents
 * @returns {string}
 */
function formatEurosPlain(cents) {
  const euros = cents / 100;
  return euros.toFixed(2);
}

/**
 * Escape a field for CSV: wrap in quotes if needed, double internal quotes.
 * @param {string} field
 * @returns {string}
 */
function escapeCsvField(field) {
  if (field.includes(',') || field.includes('"')) {
    return '"' + field.replace(/"/g, '""') + '"';
  }
  return field;
}

/**
 * Export invoices as CSV.
 * @param {Array<object>} invoices
 * @returns {string}
 */
export function exportCsv(invoices) {
  const lines = [];

  // Header
  lines.push('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');

  // Data rows
  for (const inv of invoices) {
    const totals = invoiceTotals(inv);
    const due = balanceDue(inv);

    const fields = [
      inv.number || '',
      escapeCsvField(inv.customerName || ''),
      inv.issueDate || '',
      inv.dueDate || '',
      inv.status || '',
      formatEurosPlain(totals.subtotal),
      formatEurosPlain(totals.discount),
      formatEurosPlain(totals.vat),
      formatEurosPlain(totals.total),
      formatEurosPlain(due),
    ];

    lines.push(fields.join(','));
  }

  return lines.join('\n') + '\n';
}
</file>

<file path="src/invoices.js">
import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    const [year, month] = issueDate.split('-').map(Number);
    const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
    return `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;
  }
  return null;
}

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate issueDate
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate terms
  if (!['NET14', 'NET30', 'EOM'].includes(terms)) return fail('TERMS_INVALID');

  // Calculate due date
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate lines array
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discountPercent: explicit value wins, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate and get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    customerName: customer.name,
    issueDate,
    terms,
    dueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line: qty times unitPrice (in cents).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate VAT for a single line: (lineTotal - discount) * vatRate / 100, rounded per line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }}
 * @returns {number}
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = total * (line.discountPercent ?? 0) / 100;
  const discountedTotal = total - discount;
  const vatRate = line.vatRate ?? 0;
  const vat = discountedTotal * vatRate / 100;
  return roundCents(vat);
}

/**
 * Calculate invoice totals: subtotal, discount, vat, voucher, and total.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { code: string, amount: number } }}
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => {
    const lineTotalAmount = lineTotal(line);
    const lineDiscount = lineTotalAmount * (line.discountPercent ?? 0) / 100;
    return sum + lineDiscount;
  }, 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

/**
 * Add a line to an invoice or increase qty if the SKU is already on it.
 * @param {object} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discountPercent
  const finalDiscountPercent = discountPercent ?? 0;
  if (typeof finalDiscountPercent !== 'number' || finalDiscountPercent < 0 || finalDiscountPercent > 100) {
    return fail('DISCOUNT_INVALID');
  }

  // Validate and get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLine = {
    sku,
    name: product.name,
    qty,
    unitPrice: product.unitPrice,
    vatRate: product.vatRate,
    discountPercent: finalDiscountPercent,
  };

  // Check if SKU already on invoice
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  const newLines =
    existingLineIndex === -1
      ? [...invoice.lines, newLine]
      : invoice.lines.map((line, i) => (i === existingLineIndex ? { ...line, qty: line.qty + qty } : line));

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {object} invoice
 * @param {string} sku
 */
export function removeLine(invoice, sku) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check line exists
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check it's not the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice (change status to 'issued' and assign a number).
 * @param {object} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already used
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Apply a voucher to a draft invoice (fixed amount off after VAT).
 * @param {object} invoice
 * @param {{ code: string, amount: number }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check no voucher already applied
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}
